import { BarChartAdapter } from '@dreadnought/react/unstyled';
const categories = [{id:'one',label:'One'},{id:'two',label:'Two'}];
const series = [{id:'a',label:'A',values:{one:20,two:-10}}];
export function Example() { return <BarChartAdapter label="Баланс" categories={categories} series={series} domain={[-20,40]} width={500} height={300} />; }

import { BarChartAdapter, useBarChart } from '@dreadnought/react/unstyled';
const categories=[{id:'one',label:'One'}]; const series=[{id:'a',label:'A',values:{one:10}}];
function Summary() { const {visible}= useBarChart(); return <p>Видимых серий: {visible.length}</p>; }
export function Example() { return <BarChartAdapter label="Данные" categories={categories} series={series} domain={[0,20]}><Summary /><BarChartAdapter.Legend>{({defaultContent}) => <span>{defaultContent}</span>}</BarChartAdapter.Legend><BarChartAdapter.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</BarChartAdapter.Plot><BarChartAdapter.Table /><BarChartAdapter.Pagination /><BarChartAdapter.Empty /></BarChartAdapter>; }
